@push('scripts')<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.datatables.net/2.3.2/js/dataTables.min.js"></script><script src="https://cdn.datatables.net/2.3.2/js/dataTables.bootstrap5.min.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{const table=new DataTable('#inscritosTable',{processing:true,serverSide:true,order:[[0,'desc']],pageLength:@json($estadoTabela['por_pagina']),displayStart:@json(($estadoTabela['page']-1)*$estadoTabela['por_pagina']),search:{search:@json($estadoTabela['pesquisar'])},ajax:@json(route('submissoes.inscritos.dados',$submissao, false)),columns:[{data:'id'},{data:'titulo_trabalho'},{data:'email'},{data:'autores'},{data:'status'},{data:'nota'},{data:'situacao'},{data:'updated_at'},{data:'acoes',orderable:false,searchable:false}],language:{processing:'Carregando...',emptyTable:'Nenhum trabalho enviado.',info:'Exibindo _START_ a _END_ de _TOTAL_ trabalhos',infoEmpty:'Nenhum trabalho encontrado',lengthMenu:'Exibir _MENU_',search:'Pesquisar:',zeroRecords:'Nenhum trabalho encontrado.',paginate:{next:'Próxima',previous:'Anterior'}}});const feedback=document.getElementById('actionFeedback');const mostrarFeedback=(mensagem,erro=false)=>{feedback.querySelector('span').textContent=mensagem;feedback.classList.remove('d-none','alert-danger','alert-success');feedback.classList.add('show',erro?'alert-danger':'alert-success')};document.getElementById('inscritosTable').onclick=async e=>{const botao=e.target.closest('[data-action-url]');if(!botao)return;const definitivo=botao.dataset.action==='force-delete';const pergunta=definitivo?'Excluir este trabalho definitivamente? Os dados e autores não poderão ser recuperados.':'Restaurar este trabalho para o usuário?';if(!confirm(pergunta))return;botao.disabled=true;try{const resposta=await fetch(botao.dataset.actionUrl,{method:botao.dataset.method,credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':@json(csrf_token())}});const dados=await resposta.json();if(!resposta.ok)throw new Error(dados.message);mostrarFeedback(dados.message);table.ajax.reload(null,false)}catch(erro){mostrarFeedback(erro.message||'Falha na operação.',true);botao.disabled=false}};document.getElementById('inscritosTable').addEventListener('change',async e=>{const campo=e.target.closest('[data-status-url]');if(!campo)return;const anterior=campo.dataset.statusAtual;campo.disabled=true;try{const resposta=await fetch(campo.dataset.statusUrl,{method:'PATCH',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({status:campo.value})});const dados=await resposta.json();if(!resposta.ok)throw new Error(dados.message);campo.dataset.statusAtual=campo.value;mostrarFeedback(dados.message);table.ajax.reload(null,false)}catch(erro){campo.value=anterior;mostrarFeedback(erro.message||'Falha ao alterar o status.',true)}finally{campo.disabled=false}})});</script>@endpush
